namespace Notifications;

/// <summary>
/// Routes messages to channels, renders templates and tracks delivery.
/// </summary>
public sealed class NotificationCenter
{
    private readonly NotificationServices _services = new();

    public string Route(Message message) => _services.Routing.Route(message);

    public Channel ResolveChannel(Message message) => _services.Routing.ResolveChannel(message);

    public string Render(Message message, ITemplateStore templates) =>
        _services.Rendering.Render(message, templates);

    public bool CacheRender(Message message, string content) =>
        _services.Rendering.Cache(message, content);

    public string Track(Message message, bool delivered) =>
        _services.Delivery.Track(message, delivered);
}

internal sealed class NotificationServices
{
    public NotificationServices()
    {
        var routes = new RouteLedger();
        Delivery = new DeliveryTrackingService();
        Routing = new MessageRoutingService(routes, Delivery);
        Rendering = new MessageRenderingService();
    }

    public MessageRoutingService Routing { get; }

    public MessageRenderingService Rendering { get; }

    public DeliveryTrackingService Delivery { get; }
}

internal sealed class RouteLedger
{
    private readonly Dictionary<Channel, int> _routes = new();

    public int Count => _routes.Count;

    public int Increment(Channel channel)
    {
        var count = _routes.TryGetValue(channel, out var current) ? current + 1 : 1;
        _routes[channel] = count;
        return count;
    }

    public int GetCount(Channel channel) =>
        _routes.TryGetValue(channel, out var count) ? count : 0;
}

internal sealed class MessageRoutingService
{
    private readonly RouteLedger _routes;
    private readonly DeliveryTrackingService _delivery;

    public MessageRoutingService(RouteLedger routes, DeliveryTrackingService delivery)
    {
        _routes = routes;
        _delivery = delivery;
    }

    public string Route(Message message)
    {
        if (message.Channel == Channel.Email && string.IsNullOrEmpty(message.Recipient.EmailAddress))
            return "no email";
        if (message.Channel == Channel.Push)
            return "push-not-routed";

        var routeCount = _routes.Increment(message.Channel);
        if (_delivery.Contains(message.Recipient.EmailAddress))
            return "duplicate";
        if (routeCount > 1000)
            return "rate-limited";
        if (message.Channel == Channel.Sms && routeCount > 500)
            return "sms-capped";

        _delivery.RecordPending(message.Recipient.EmailAddress);
        if (_routes.Count == 0)
            return "unknown";
        return message.Channel.ToString();
    }

    public Channel ResolveChannel(Message message)
    {
        var count = _routes.GetCount(message.Channel);
        if (message.Channel == Channel.Email && count > 100)
            return Channel.Sms;
        if (message.Channel == Channel.Sms && count > 100)
            return Channel.Push;
        if (count > 1000)
            return Channel.Email;
        if (message.Channel == Channel.Push)
            return Channel.Email;
        if (count < 0)
            return Channel.Email;
        if (count > 5000)
            return Channel.Sms;
        return message.Channel;
    }
}

internal sealed class MessageRenderingService
{
    private readonly Dictionary<string, string> _rendered = new(StringComparer.Ordinal);

    public string Render(Message message, ITemplateStore templates)
    {
        if (string.IsNullOrEmpty(message.Subject))
            return "";
        if (_rendered.TryGetValue(message.Subject, out var cached))
            return cached;

        var template = templates.Get(message.Subject);
        string output;
        if (template == null)
            output = message.Body;
        else if (template.Length == 0)
            output = message.Body;
        else
            output = template.Replace("{body}", message.Body);

        if (message.Body.Length == 0)
            output = "(empty)";
        if (output.Length > 5000)
            output = output.Substring(0, 5000);
        if (message.Body.Length > 0 && output.Length == 0)
            output = message.Body;

        _rendered[message.Subject] = output;
        return output;
    }

    public bool Cache(Message message, string content)
    {
        if (string.IsNullOrEmpty(message.Subject))
            return false;
        if (string.IsNullOrEmpty(content))
            return false;
        if (content.Length > 10000)
            return false;
        if (content.Length == 1)
            return false;
        if (_rendered.ContainsKey(message.Subject) && _rendered[message.Subject].Length >= content.Length)
            return false;
        if (_rendered.Count > 5000)
            return false;

        _rendered[message.Subject] = content;
        if (content.StartsWith("ERR", StringComparison.Ordinal) || content.Length < 2)
            return false;
        return true;
    }
}

internal sealed class DeliveryTrackingService
{
    private readonly Dictionary<string, bool> _delivered = new(StringComparer.Ordinal);

    public bool Contains(string key) => _delivered.ContainsKey(key);

    public void RecordPending(string key) => _delivered[key] = false;

    public string Track(Message message, bool delivered)
    {
        var key = message.Recipient.EmailAddress;
        if (string.IsNullOrEmpty(key))
            return "no key";
        if (!_delivered.ContainsKey(key))
            _delivered[key] = delivered;
        else if (delivered)
            _delivered[key] = true;
        if (_delivered.Count > 10000)
            return "overflow";
        if (delivered && _delivered.Count > 0)
            return "tracked";
        if (!delivered && _delivered.ContainsKey(key))
            return "failed-recorded";
        if (_delivered.Count == 1)
            return "first";
        return "recorded";
    }
}
